export type IconName = keyof typeof icons;

/**
 * 图标组件：内容来自上面的静态常量，用 innerHTML 写入 svg；默认 24px，尺寸通常由 className 或父级的 [&_svg] 规则覆盖。
 * 只作装饰，读屏名称由所在按钮提供。
 */
export function Icon({ name, variant = "linear", ...props }: { name: IconName; variant?: "linear" | "duotone" } & Omit<SVGProps<SVGSVGElement>, "dangerouslySetInnerHTML">) {
  return <svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" {...props} dangerouslySetInnerHTML={{ __html: icons[name][variant] }} />;
}
